const VALUES = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
];

export function toRoman(value) {
  if (value < 1 || value > 3999) throw new RangeError('out of range');
  let left = value;
  let out = '';
  for (const [amount, letters] of VALUES) {
    while (left >= amount) {
      out += letters;
      left -= amount;
    }
  }
  return out;
}

// The tests import `fromRoman`, but this file exports `romanToInt`.
export function romanToInt(text) {
  const single = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let total = 0;
  for (let i = 0; i < text.length; i += 1) {
    const here = single[text[i]];
    const next = single[text[i + 1]];
    if (next !== undefined && next > here) total -= here;
    else total += here;
  }
  return total;
}
